package com.oea.engine.graphics

import java.util.concurrent.ConcurrentHashMap

/**
 * Procedural character material textures. They are generated once per key and
 * regenerated by [Texture] after a GL context loss. Because the colour remains
 * in [Material], the same normalised pattern works for every outfit colour.
 */
object CharTextures {
    private val cache = ConcurrentHashMap<String, Texture>()

    fun forKey(key: String?): Texture? {
        val k = key?.ifBlank { "fabric" } ?: return null
        if (k == "none" || k == "flat") return null
        return cache.getOrPut(k) {
            when (k) {
                "skin_pores" -> Textures.noise(128, 18f, 91L, 0xFFE7E7E7.toInt(), 0xFFFFFFFF.toInt(), 3)
                "skin_smooth" -> Textures.noise(64, 5f, 93L, 0xFFF1F1F1.toInt(), 0xFFFFFFFF.toInt(), 2)
                "cotton" -> Textures.noise(128, 28f, 11L, 0xFFE8E8E8.toInt(), 0xFFFFFFFF.toInt(), 3)
                "cotton_fine" -> Textures.noise(128, 46f, 12L, 0xFFECECEC.toInt(), 0xFFFFFFFF.toInt(), 3)
                "knit" -> Textures.noise(128, 20f, 21L, 0xFFDCDCDC.toInt(), 0xFFFFFFFF.toInt(), 4)
                "fleece" -> Textures.noise(128, 12f, 31L, 0xFFE1E1E1.toInt(), 0xFFFFFFFF.toInt(), 3)
                "tactical" -> Textures.noise(128, 9f, 44L, 0xFFD0D0D0.toInt(), 0xFFFFFFFF.toInt(), 4)
                "canvas" -> Textures.noise(128, 14f, 51L, 0xFFD2D2D2.toInt(), 0xFFFDFDFD.toInt(), 3)
                "leather" -> Textures.noise(128, 10f, 61L, 0xFFBDBDBD.toInt(), 0xFFF1F1F1.toInt(), 3)
                "rubber" -> Textures.noise(64, 7f, 71L, 0xFF8A8A8A.toInt(), 0xFFC5C5C5.toInt(), 2)
                "metal" -> Textures.noise(128, 5f, 81L, 0xFFB8B8B8.toInt(), 0xFFF4F4F4.toInt(), 2)
                else -> Textures.noise(64, 10f, k.hashCode().toLong(), 0xFFE4E4E4.toInt(), 0xFFFFFFFF.toInt(), 2)
            }
        }
    }

    fun clear() = cache.values.forEach { it.dispose() }.also { cache.clear() }
}
